export type NomeDeIconeDesk = keyof typeof DESENHOS;

export function IconeDesk({
  nome,
  tamanho = 24,
  ...resto
}: { nome: NomeDeIconeDesk; tamanho?: number } & Omit<SVGProps<SVGSVGElement>, 'name'>) {
  const desenho = DESENHOS[nome];
  return (
    <svg
      width={tamanho}
      height={tamanho}
      viewBox={desenho.caixa}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      {...resto}
    >
      {desenho.partes.map((d) => (
        <path key={d.slice(0, 24)} d={d} fillRule={desenho.parOuImpar ? 'evenodd' : undefined} />
      ))}
    </svg>
  );
}
